import { useCallback, useEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [view, setView] = useState({ results: [], phase: "idle" });

  const valueRef = useRef("");
  const timerRef = useRef(null);
  const latestRequestRef = useRef(null);

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const invalidateRequest = useCallback(() => {
    const request = latestRequestRef.current;
    latestRequestRef.current = null;

    if (request && request.state === "pending") {
      request.state = "aborted";
      request.controller.abort();
    }
  }, []);

  const resetSearch = useCallback(() => {
    clearTimer();
    invalidateRequest();
    setView((current) =>
      current.phase === "idle" && current.results.length === 0
        ? current
        : { results: [], phase: "idle" }
    );
  }, [clearTimer, invalidateRequest]);

  const startRequest = useCallback(
    (query, force = false) => {
      clearTimer();

      if (query.length < minChars) {
        resetSearch();
        return;
      }

      const previous = latestRequestRef.current;

      if (
        !force &&
        previous &&
        previous.query === query &&
        !previous.controller.signal.aborted &&
        (previous.state === "pending" || previous.state === "success")
      ) {
        return;
      }

      const controller = new AbortController();
      const request = { query, controller, state: "pending" };
      latestRequestRef.current = request;

      const isCurrent = () =>
        latestRequestRef.current === request && !controller.signal.aborted;

      if (previous) {
        previous.controller.abort();
      }

      if (!isCurrent()) {
        return;
      }

      setView((current) => ({
        results: current.results,
        phase: "loading",
      }));

      const handleFailure = (error) => {
        if (!isCurrent()) {
          return;
        }

        if (error?.name === "AbortError") {
          request.state = "aborted";
          setView((current) => ({
            results: current.results,
            phase: "idle",
          }));
        } else {
          request.state = "failed";
          setView({ results: [], phase: "error" });
        }
      };

      try {
        Promise.resolve(search(query, { signal: controller.signal })).then(
          (results) => {
            if (!isCurrent()) {
              return;
            }

            request.state = "success";
            setView({ results, phase: "success" });
          },
          handleFailure
        );
      } catch (error) {
        handleFailure(error);
      }
    },
    [clearTimer, minChars, resetSearch, search]
  );

  const scheduleSearch = useCallback(
    (inputValue) => {
      clearTimer();

      const query = inputValue.trim();
      if (query.length < minChars) {
        resetSearch();
        return;
      }

      timerRef.current = setTimeout(() => {
        timerRef.current = null;
        startRequest(query);
      }, debounceMs);
    },
    [clearTimer, debounceMs, minChars, resetSearch, startRequest]
  );

  useEffect(() => {
    scheduleSearch(valueRef.current);
    return clearTimer;
  }, [clearTimer, scheduleSearch]);

  useEffect(() => {
    return () => {
      clearTimer();
      invalidateRequest();
    };
  }, [clearTimer, invalidateRequest]);

  const handleChange = (event) => {
    const nextValue = event.target.value;
    valueRef.current = nextValue;
    setValue(nextValue);
    scheduleSearch(nextValue);
  };

  const statusText =
    view.phase === "loading"
      ? "Searching..."
      : view.phase === "success" && view.results.length === 0
        ? "No results"
        : "";

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{statusText}</div>
      <ul aria-label="Results">
        {view.results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
      {view.phase === "error" && (
        <div role="alert">
          Something went wrong{" "}
          <button
            type="button"
            onClick={() => startRequest(valueRef.current.trim(), true)}
          >
            Retry
          </button>
        </div>
      )}
    </div>
  );
}
